// Claude's review tests for A15 (import an OpenAPI file). agy: do not edit this file.
import { expect, test } from '@playwright/test';
import { emptyState, newProject, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

const YAML = `openapi: 3.0.3
info:
  title: Goals API
  version: "1"
servers:
  - url: /api
paths:
  /goals:
    get:
      operationId: listGoals
      responses:
        "200":
          description: ok
          content:
            application/json:
              example:
                goals:
                  - id: 1
                    title: From the spec
  /goals/{id}:
    get:
      responses:
        "200":
          content:
            application/json:
              schema:
                type: object
                properties:
                  id: { type: integer }
                  done: { type: boolean }
`;

test('a YAML OpenAPI file becomes a scenario that answers the page', async () => {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [newProject('p1', fixture.origin)] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  try {
    await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('import').setInputFiles({ name: 'goals.yaml', mimeType: 'application/yaml', buffer: Buffer.from(YAML) });
    await expect(panel.getByTestId('import-choice')).toBeVisible();
    await panel.getByTestId('import-replace').click();
    await expect(panel.getByTestId('import-summary')).toHaveText('2 mocks from 2 operations');
    const p = (await readState()).projects[0]!;
    expect(p.scenarios.map((s) => s.name)).toEqual(['Default', 'Goals API']);

    await page.reload();
    const got = await page.evaluate(async () => ({
      list: await (await fetch('/api/goals')).json(),
      one: await (await fetch('/api/goals/5')).json(),
    }));
    expect(got).toEqual({ list: { goals: [{ id: 1, title: 'From the spec' }] }, one: { id: 0, done: true } });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a YAML file that is not OpenAPI shows an error', async () => {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [newProject('p1', fixture.origin)] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  try {
    await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('import').setInputFiles({ name: 'x.yaml', mimeType: 'application/yaml', buffer: Buffer.from('a: 1\nb: [2, 3]\n') });
    await expect(panel.getByTestId('import-error')).toBeVisible();
    await expect(panel.getByTestId('import-choice')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});
